const systemErrorMarkers: Array<[string, string]> = [
  ['no space left on device', '磁盘空间不足'],
  ['not enough space', '磁盘空间不足'],
  ['disk quota exceeded', '磁盘配额已用完'],
  ['read-only file system', '磁盘为只读状态，无法写入'],
  ['permission denied', '没有操作权限'],
  ['operation not permitted', '操作不被允许'],
  ['input/output error', '读取或写入失败'],
  ['too many open files', '打开的文件过多'],
  ['device or resource busy', '设备或资源正忙'],
]

function localizeErrorMessage(message: unknown) {
  const raw = String(message || '').trim()
  if (!raw) return '操作失败，请稍后重试'
  const lower = raw.toLowerCase()
  for (const [marker, localized] of systemErrorMarkers) {
    if (lower.includes(marker)) return localized
  }
  if (raw.startsWith('invalid age public key:')) return 'Age 公钥格式无效'
  if (raw.startsWith('invalid trusted proxy address ')) return `受信代理地址无效：${raw.slice('invalid trusted proxy address '.length)}`
  if (raw.startsWith('subscription plan(s) are still applying a change:')) return '相关订阅套餐正在应用变更，完成后再删除'
  if (raw.startsWith('plan version is still applying; retry after it settles:')) return '相关订阅套餐正在应用变更，完成后再删除'
  return errorMessages[raw] || errorMessages[raw.toLowerCase()] || raw
}

function apiErrorMessage(data: any, res: Response) {
  const detail = typeof data?.message === 'string' ? data.message.trim() : ''
  if (detail) return detail
  return localizeErrorMessage(data?.error || res.statusText)
}

function apiRequestError(data: any, res: Response) {
  const error = new Error(apiErrorMessage(data, res))
  ;(error as any).status = res.status
  return error
}

function showToast(setToast: React.Dispatch<React.SetStateAction<ToastState>>, message: unknown, kind: ToastKind = 'error') {
  setToast({ id: Date.now(), kind, message: kind === 'error' ? localizeErrorMessage(message) : String(message) })
}

function TopToast({ toast, onClose }: { toast: ToastState; onClose: (id: number) => void }) {
  const viewport = <div className="top-toast-viewport">
    <AnimatePresence initial={false} mode="wait">
      {toast && <Toast key={toast.id} message={toast.message} kind={toast.kind} onClose={() => onClose(toast.id)} />}
    </AnimatePresence>
  </div>
  return typeof document === 'undefined' ? viewport : createPortal(viewport, document.body)
}

function IconButton({ label, onClick, children, className = '', busy = false }: { label: string; onClick: () => void; children: React.ReactNode; className?: string; busy?: boolean }) {
  return <button className={['ghost icon-button', className].filter(Boolean).join(' ')} onClick={onClick} aria-label={label} title={label} aria-busy={busy}>{children}</button>
}

